-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN
  -- dabigatran etexilate (CIS 60292648)
  m := pg_temp.jp_matrice_by_norm('dabigatran etexilate');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : agents antithrombotiques, inhibiteurs directs de la thrombine, Code ATC : B01AE07');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention primaire des événements thromboemboliques veineux (ETEV) chez les patients adultes ayant bénéficié d’une chirurgie programmée pour prothèse totale de hanche ou de genou.', 'Traitement des thromboses veineuses profondes (TVP) et des embolies pulmonaires (EP), et prévention des récidives de TVP et d’EP chez l’adulte.', 'Traitement des ETEV et prévention des récidives d’ETEV chez les patients pédiatriques âgés de moins de 18 ans.', 'Pour connaître les formes pharmaceutiques appropriées en fonction de l’âge, voir rubrique 4.2.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1', 'Insuffisance rénale sévère (ClCr', 'DFGe 2 chez les patients pédiatriques', 'Saignement évolutif cliniquement significatif', 'Lésion ou maladie jugée à risque significatif de saignement majeur.', 'Insuffisance hépatique ou maladie du foie susceptible d’avoir un impact sur la survie', 'Porteurs de prothèses valvulaires cardiaques nécessitant un traitement anticoagulant (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Risque hémorragique', 'Au cours du traitement, un saignement peut se produire à n’importe quel endroit.', 'Une chute inexpliquée du taux d’hémoglobine et/ou de l’hématocrite ou une baisse de la pression artérielle doivent faire rechercher une source de saignement.', 'L’efficacité et la sécurité de l’idarucizumab n’ont pas été établies chez les patients pédiatriques.', 'L’hémodialyse permet d’éliminer le dabigatran.', 'Dans des études cliniques, le dabigatran étexilate a été associé à des taux plus élevés de saignement gastro-intestinal (GI) majeur.', 'Un risque accru a été observé chez les personnes âgées (≥ 75 ans) pour la posologie de 150 mg deux fois par jour.', 'Facteurs de risque', 'Le tableau 5 récapitule les facteurs pouvant majorer le risque hémorragique.', 'Tableau 5 : Facteurs pouvant majorer le risque hémorragique', 'Facteur de risque', 'Facteurs pharmacodynamiques et pharmacocinétiques']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Interactions avec des transporteurs', 'Le dabigatran étexilate est un substrat du transporteur d’efflux P-gp.', 'L’administration concomitante d’un inhibiteur de la P-gp (voir tableau 9) devrait augmenter les concentrations plasmatiques de dabigatran.', 'Des diminutions de la posologie peuvent être nécessaires en cas d’association avec certains inhibiteurs de la P-gp (voir rubriques 4.2, 4.3, 4.4 et 5.1).', 'Tableau 9 : Interactions avec des transporteurs', 'Inhibiteurs de la P-gp', 'Utilisation concomitante contre-indiquée (voir rubrique 4.3)', 'Kétoconazole', 'Dronédarone', 'Itraconazole, ciclosporine', 'Compte tenu des résultats in vitro, un effet similaire à celui obtenu avec le kétoconazole peut être attendu.', 'Glécaprévir/ pibrentasvir']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Ils sont classés par système classe organe (SOC) et fréquence selon la convention suivante : très fréquent (≥ 1/10) ; fréquent (≥ 1/100, ≥ 1/1 000, ≥ 1/10 000, Tableau 12 : Effets indésirables', 'Peu fréquent']);

  -- warfarine (CIS 64631925)
  m := pg_temp.jp_matrice_by_norm('warfarine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTITHROMBOTIQUES, code ATC : B01AA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention des complications thrombo-emboliques des infarctus du myocarde compliqués: thrombus mural, dysfonction ventriculaire gauche sévère, dyskinésie emboligène..., en relais de l''héparine.', 'Traitement des thromboses veineuses profondes et de l''embolie pulmonaire ainsi que la prévention de leurs récidives, en relais de l''héparine.', 'Ces indications sont détaillées en rubrique 4.2 surveillance biologique.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament est contre-indiqué dans les cas suivants :', 'Hypersensibilité connue à la warfarine, ou à l’un des excipients', 'Hypertension maligne', 'Insuffisance hépatique sévère', 'En cas d’association avec les médicaments suivants (voir rubrique 4.5.) :', 'o L’acide acétylsalicylique :', '§ pour des doses anti-inflammatoires d’acide acétylsalicylique (> 1 g par prise et/ou > 3 g par jour),', '§ pour des doses antalgiques ou antipyrétiques (> 500 mg par prise et/ou', 'o Le miconazole utilisé par voie gastroduodénal', 'o Les AINS pyrazolés : la phénylbutazone (toutes les formes de phénylbutazone y compris locales)', 'En cas d’association avec le millepertuis', 'Grossesse, excepté chez les femmes enceintes portant une valve cardiaque mécanique, qui présentent un risque élevé de thromboembolie (voir rubriques 4.4 et 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Le risque hémorragique est le principal risque d’un traitement par AVK.', 'Le risque de thrombose en cas de traitement insuffisant (sous dosé) est également à prendre en compte.', 'Ce médicament est généralement déconseillé :', 'en cas de risque hémorragique', 'La décision de débuter ou de continuer le traitement par AVK, doit être pris en fonction du rapport bénéfice/risque propre à chaque patient et à chaque situation.', 'Les situations à risque sont en particulier les suivantes :', 'o lésion organique susceptible de saigner,', 'o intervention récente neuro chirurgicale ou ophtalmologique ou possibilité de reprise chirurgicale,', 'o ulcère gastro duodénal récent ou en évolution,', 'o varices œsophagiennes,', 'o hypertension artérielle non contrôlée,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Les médicaments susceptibles d''interagir avec les AVK sont très nombreux.', 'Si un autre traitement doit être débuté, modifié ou supprimé, il est nécessaire d''effectuer un contrôle de l''INR 3 à 4 jours après chaque modification.', 'Consultez attentivement la notice de tout médicament pris en même temps que COUMADINE.', 'Vous obtiendrez toute information sur les interactions avec COUMADINE ou sur les réactions adverses se rapportant aux saignements.', '+ Interactions avec le CYP 450', 'Le cytochrome P450, incluant les CYP2C9, 2C19, 2C8, 2C18, 1A2, et 3A4 est impliqué dans le métabolisme de la warfarine.', 'Les inhibiteurs du CYP2C9, 1A2, et/ou 3A4 ont le potentiel d’augmenter l’effet de la warfarine.', 'Les inducteurs du CYP2C9, 1A2, et/ou 3A4 ont le potentiel de diminuer l’effet (diminution de l’INR).', 'Associations contre-indiquées', '+ Acide acétylsalicylique', '+ AINS pyrazolé : phénylbutazone', 'Pour toutes les formes de phenylbutazone, y compris locales :']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables sont classés par système organe et par fréquence, selon la règle suivante : très fréquent (> 10) ; fréquent (> 1/100, 1/1000 ; 1/10 000,', 'Les manifestations hémorragiques représentent la complication la plus fréquente du traitement.', 'Une hémorragie, pouvant varier d’un saignement léger à grave (y compris d’issue fatale), peut survenir au cours du traitement par COUMADINE.', 'Une hémorragie rétropéritonéale peut également se produire.', 'voies respiratoires (épistaxis, hémoptysie), y compris de rares cas d’hémorragie alvéolaire pulmonaire']);

  -- acenocoumarol (CIS 62148714)
  m := pg_temp.jp_matrice_by_norm('acenocoumarol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : antithrombotiques, code ATC : B01AA07');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention des complications thrombo-emboliques des infarctus du myocarde compliqués : thrombus mural, dysfonction ventriculaire gauche sévère, dyskinésie emboligène, en relais de l’héparine.', 'Traitement des thromboses veineuses profondes et de l’embolie pulmonaire ainsi que la prévention de leur récidive, en relais de l’héparine.', 'Ces indications sont détaillées en rubrique 4.2 surveillance biologique.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active, l’acénocoumarol (ou aux dérivés coumariniques) ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Insuffisance hépatique sévère', 'Hypertension sévère', 'En cas d’association avec les médicaments ou composés suivants (voir rubrique 4.5) :', '1. l’acide acétylsalicylique :', 'o Pour des doses anti-inflammatoires d’acide acétylsalicylique (≥ 1 g par prise et/ou ≥ 3 g par jour),', 'o Pour des doses antalgiques ou antipyrétiques (≥ 500 mg par prise et/ou 2. le miconazole utilisé par voie générale ou en gel buccal,', '3. le millepertuis.', 'Grossesse, excepté chez les femmes enceintes portant une valve cardiaque mécanique, qui présentent un risque élevé de thromboembolie (voir rubriques 4.4 et 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'Le risque hémorragique est le principal risque d’un traitement par AVK.', 'Le risque de thrombose en cas de traitement insuffisant (sous dosé) est également à prendre en compte.', 'Ce médicament est généralement déconseillé :', 'en cas de risque hémorragique.', 'La décision de débuter ou de continuer le traitement par AVK, doit être prise en fonction du rapport bénéfice/risque propre à chaque patient et à chaque situation.', 'Les situations à risque sont en particulier les suivantes :', 'o lésion organique susceptible de saigner,', 'o intervention récente neuro chirurgicale ou ophtalmologique ou possibilité de reprise chirurgicale,', 'o ulcère gastro duodénal récent ou en évolution,', 'o varices œsophagiennes,', 'o hypertension artérielle non contrôlée,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Anti-infectieux et hémostase', 'De nombreux cas d’augmentation de l’activité des antivitamines K ont été rapportés chez des patients recevant des antibiotiques.', 'Le contexte infectieux ou inflammatoire marqué, l’âge et l’état général du patient apparaissent comme des facteurs de risque.', 'Dans ces circonstances, il apparaît difficile de faire la part entre la pathologie infectieuse et son traitement dans la survenue du déséquilibre de l’INR.', 'Certaines céphalosporines (céfamandole, ceftriaxone, céfazoline), la clindamycine, semblent interagir au niveau de l’hémostase avec apparition d’anticorps anti facteur V.', 'Enfin, la tigécycline et le danazol possèdent une action fibrinolytique propre.', 'AVK et INR', 'Chez un patient traité par antivitamines K, il convient de contrôler l’INR à chaque initiation ou suppression d’un ou plusieurs médicaments.', 'La modification soudaine des habitudes alimentaires doit être également prise en compte et la régularité est préconisée pour le maintien à l’équilibre de l’INR.', 'Les aliments riches en vitamine K sont essentiellement représentés par les choux, épinards, brocolis, certaines salades.', 'Associations contre-indiquées', '+ Acide acétylsalicylique']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Hémorragies : Les manifestations hémorragiques représentent la complication la plus fréquente du traitement avec MINI-SINTROM.', 'Toute structure anatomique peut en être le point de départ et/ou le siège : hémorragie ou hématome intracérébral, hématome du psoas, hémorragie intra-abdominale, hémorragie intra-articulaire.', 'Il peut s’agir d’hémorragies non graves par exemple : hématome, épistaxis, gingivorragie.', 'Anémie (secondaire à une hémorragie, un saignement)', 'Fréquent :']);

  -- fluindione (CIS 68133651)
  m := pg_temp.jp_matrice_by_norm('fluindione');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTITHROMBOTIQUES, code ATC : B01AA.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Renouvellement d’un traitement équilibré par fluindione dans les indications suivantes:', 'Prévention des complications thrombo-emboliques des infarctus du myocarde compliqués : thrombus mural, dysfonction ventriculaire gauche sévère, dyskinésie emboligène ', 'Traitement des thromboses veineuses profondes et de l’embolie pulmonaire ainsi que la prévention de leurs récidives.', 'Ces indications sont détaillées en rubrique 4.2 / Surveillance biologique.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament est contre-indiqué dans les cas suivants :', 'Hypersensibilité à la fluindione ou à l’un des excipients mentionnés à la rubrique 6.1, ou aux dérivés de l''indanédione,', 'Insuffisance hépatique sévère,', 'En cas d''association avec les médicaments suivants (voir rubrique 4.5) :', 'o l''acide acétylsalicylique :', '§ pour des doses anti-inflammatoires d''acide acétylsalicylique (≥ 1 g par prise et/ou ≥ 3 g par jour),', '§ pour des doses antalgiques ou antipyrétiques (≥ 500 mg par prise et/ou o le miconazole utilisé par voie générale ou en gel buccal,', 'o les AINS pyrazolés : la phénylbutazone (toutes ses formes y compris locales),', 'En cas d''association avec le millepertuis (plante utilisée en phytothérapie),', 'En cas de grossesse, excepté chez les femmes enceintes portant une valve cardiaque mécanique, qui présentent un risque élevé de thromboembolie (voir rubriques 4.4 et 4.6),', 'En cas d''allaitement,', 'Chez les patients présentant une allergie au blé (autre que la maladie cœliaque).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'En cas de traitement par AVK, une attention particulière sera portée aux fonctions cognitives du patient ainsi qu''au contexte psychologique et social, en raison des contraintes liées au traitement.', 'En raison du risque de manifestations immuno-allergiques, survenant principalement dans les', '6 premiers mois de traitement, PREVISCAN ne doit pas être prescrit lors de l’initiation d’un traitement anticoagulant (voir rubrique 4.8)', 'Ce médicament est généralement déconseillé :', 'En cas de risque hémorragique.', 'La décision de continuer le traitement par AVK doit être prise en fonction du rapport bénéfice/risque propre à chaque patient et à chaque situation.', 'Les situations à risque sont en particulier les suivantes :', 'o lésion organique susceptible de saigner,', 'o intervention récente neuro-chirurgicale ou ophtalmologique ou possibilité de reprise chirurgicale,', 'o ulcère gastro-duodénal récent ou en évolution,', 'o varices œsophagiennes,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Les médicaments susceptibles d''interagir avec les AVK sont très nombreux.', 'Si un autre traitement doit être débuté, modifié ou supprimé, il est nécessaire d''effectuer un contrôle de l''INR 3 à 4 jours après chaque modification.', 'Associations contre-indiquées', '+ Acide acétylsalicylique (aspirine à forte dose)', 'Pour des doses anti-inflammatoires d''acide acétylsalicylique (≥ 1 g par prise et/ou ≥ 3 g par jour)', 'Pour des doses antalgiques ou antipyrétiques (≥ 500 mg par prise et/ou Majoration du risque hémorragique, notamment en cas d''antécédent d''ulcère gastro-duodénal.', '+ AINS pyrazolés', 'Pour toutes les formes de phénylbutazone, y compris locales :', 'Augmentation du risque hémorragique de l''anticoagulant oral (inhibition de la fonction plaquettaire et agression de la muqueuse gastroduodénale par les anti-inflammatoires non stéroïdiens).', '+ Miconazole (voie générale et gel buccal)', 'Hémorragies imprévisibles qui peuvent éventuellement être graves.', '+ Millepertuis']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables sont classés par système organe et par fréquence, selon la règle suivante : très fréquent (>1/100, 1/1 000, 1/10 000, Affections vasculaires', 'Les manifestations hémorragiques représentent la complication la plus fréquente du traitement.', 'Des cas d’hémorragies fatales ont été rapportés.', 'Toute structure anatomique peut en être le point de départ et/ou le siège : hémorragie ou hématome intracérébral, hématome du psoas, hémorragie intra-abdominale, hémorragie intra-articulaire.', 'Il peut s''agir également d''hémorragies non graves par exemple : hématome, épistaxis, gingivorragie.']);

  -- alteplase (CIS 67177673)
  m := pg_temp.jp_matrice_by_norm('alteplase');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Thrombolytiques, code ATC : B01AD02.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement thrombolytique des cathéters veineux centraux occlus y compris ceux utilisés dans l’hémodialyse.', 'Le flacon de 2 mg est la seule présentation d’altéplase recommandée pour l’utilisation dans cette indication.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité connue à la substance active ou à l''un des excipients listés à la section 6.1.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Traçabilité', 'Afin d’améliorer la traçabilité des médicaments biologiques, le nom et le numéro de lot du produit administré doivent être clairement enregistrés.', 'La présentation appropriée d’altéplase doit être choisie soigneusement et en accord avec l’utilisation prévue.', 'Seuls les flacons de 10, 20 et 50 mg sont indiqués pour ces utilisations.', 'Instillation concomitante d’héparine', 'L’instillation concomitante d’héparine avec l’altéplase n’a pas mis en évidence une amélioration du taux de restauration de la fonction du cathéter et est déconseillée.', 'Si l’héparine est considérée nécessaire pour empêcher une nouvelle occlusion, celle-ci doit être instillée séparément après la restauration de la fonction du cathéter.', 'Lésions de la paroi vasculaire et affaissement des cathéters', 'Toute pression excessive doit être évitée lorsque l’altéplase est instillé dans le cathéter.', 'Une telle force pourrait provoquer la rupture du cathéter ou l’expulsion du caillot dans la circulation.', 'Saignements :', 'L’effet indésirable le plus fréquent associé à tous les thrombolytiques dans l’ensemble des indications autorisées est le saignement.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Il n’y a pas eu d’étude d’interaction formelle réalisée avec ACTILYSE 2 mg.', '+ Médicaments agissant sur la coagulation/la fonction plaquettaire', '+ Inhibiteurs de l’enzyme de conversion de l’angiotensine', 'Un traitement concomitant par des inhibiteurs de l’enzyme de conversion de l’angiotensine pourrait augmenter le risque de survenue d’une réaction d’hypersensibilité.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Peu fréquent']);

  -- urokinase (CIS 68951171)
  m := pg_temp.jp_matrice_by_norm('urokinase');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : thrombolytique, code ATC : B01AD04.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Restauration de la perméabilité des cathéters veineux (cathéters veineux centraux et cathéters de dialyse), en cas d''obstruction liée à un thrombus en formation ou récemment formé.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Cliniques :', 'Comme tous les agents thrombolytiques, ACTOSOLV ne doit pas être utilisé dans tous les cas associés à un risque hémorragique élevé :', 'Diathèse hémorragique connue', 'Traitement concomitant par des anticoagulants oraux (par exemple warfarine)', 'Hémorragie sévère ou potentiellement dangereuse, manifeste ou récente', 'Ulcères gastroduodénaux non cicatrisés', 'Antécédents ou suspicion d''hémorragie intracrânienne', 'Suspicion d’hémorragie sous-arachnoïdienne ou antécédent d''hémorragie sous-arachnoïdienne liée à un anévrisme', 'Antécédent de lésion sévère du système nerveux central (par exemple néoplasie, anévrisme, intervention chirurgicale intracérébrale ou intrarachidienne)', 'Massage cardiaque externe traumatique récent (moins de 10 jours), accouchement, ponction récente d''un vaisseau non accessible à la compression (par exemple ponction de la veine sous-clavière ou jugulaire)', 'Hypertension artérielle sévère non contrôlée', 'Endocardite bactérienne, péricardite']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Il est impératif d''éviter en cours de traitement les injections intramusculaires et ponctions artérielles (dans les zones où les artères sont incompressibles).', 'Précautions d''emploi', 'Le risque hémorragique augmentant avec l''âge, l''indication d''une thrombolyse doit être soigneusement évaluée en fonction des risques potentiels d''accident vasculaire cérébral chez le sujet âgé.', 'Le risque hémorragique est également accru chez la femme hypertendue de petit poids.', 'En l''absence d''hémorragie majeure, la demi-vie du produit étant très courte, il semble préférable de surveiller et d''attendre, sans conseiller de traitement systématique.', 'Si nécessaire, une administration de culots globulaires et/ou de plasma frais et/ou de cryoprécipités pourra être effectuée sous surveillance biologique.', 'Dans l''indication de restauration de la perméabilité des cathéters veineux (cathéters veineux centraux et cathéters de dialyse) :', 'L''administration sous forme de perfusion doit être réservée en cas d''échec de plusieurs tentatives de désobstruction par injection directe dans le cathéter.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations à prendre en compte', '+ Acide acétylsalicylique (aspirine) - voie générale', 'Augmentation du risque hémorragique.', '+ AINS - voie générale y compris les inhibiteurs sélectifs de cox-2', '+ Antiagrégants plaquettaires', '+ Anticoagulants oraux', '+ Héparines + fondaparinux sodique']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Hémorragies (le plus souvent au point d''injection ou générales).', 'Réaction anaphylactique.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['En l''absence d''hémorragie majeure, la demi-vie du produit étant très courte, il semble préférable de surveiller et d''attendre, sans conseiller de traitement systématique.', 'Si nécessaire, une administration de culots globulaires et/ou de plasma frais et/ou de cryoprécipités pourra être effectuée sous surveillance biologique.']);

  -- phytomenadione (CIS 64639110)
  m := pg_temp.jp_matrice_by_norm('phytomenadione');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ADDITIFS POUR SOLUTION INTRAVEINEUSE / VITAMINES');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Utilisé en nutrition parentérale pour couvrir les besoins quotidiens en vitamines liposolubles (A, D2, E, K1), chez l’adulte et l’enfant de plus de 11 ans.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité aux protéines d’œuf, de soja ou d’arachide, aux substances actives, ou à l’un des excipients mentionnés à la rubrique 6.1']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'VITALIPIDE ADULTES ne doit jamais être utilisé non dilué et ne jamais être injecté directement dans une veine.', 'Précautions particulières d’emploi', 'VITALIPIDE ADULTES, émulsion à diluer pour perfusion, ne contient aucune vitamine hydrosoluble, indispensables en cas de nutrition parentérale exclusive', 'Ce médicament contient de l’huile de soja pouvant entraîner de rares réactions allergiques.', 'Des réactions d’allergies croisées ont été observées entre le soja et l’arachide.', 'Pour éviter tout surdosage, tenir compte des doses totales de vitamines liposolubles en cas d’association de plusieurs traitements contenant ces vitamines.', 'Ce médicament contient moins de 1 mmol (23 mg) de sodium par ampoule, c’est-à-dire qu’il est essentiellement « sans sodium ».']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La présence d’oligo-éléments dans la poche peut entraîner une dégradation bien que minime de la vitamine A.', 'La vitamine A peut être dégradée par la lumière (U.V).', 'La vitamine K1 antagonise les effets des anticoagulants de type coumariniques.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['VITALIPIDE ADULTES contient de l''huile de soja et peut provoquer des réactions d’hypersensibilité (urticaire, choc anaphylactique).']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Pour éviter tout surdosage, tenir compte des doses totales de vitamines liposolubles en cas d’association de plusieurs traitements contenant ces vitamines.']);

  -- acide tranexamique (CIS 63520847)
  m := pg_temp.jp_matrice_by_norm('acide tranexamique');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : anti-hémorragiques, antifibrinolytiques, code ATC : B02AA02.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention et traitement des hémorragies dues à une fibrinolyse générale ou locale chez l’adulte et l’enfant à partir d’un an.', 'Les indications spécifiques incluent :', 'Hémorragies causées par une fibrinolyse générale ou locale telles que :', 'o Ménorragies et métrorragies,', 'o Hémorragies gastro‑intestinales,', 'o Affections urinaires hémorragiques, suite à une intervention chirurgicale prostatique ou des actes chirurgicaux affectant les voies urinaires,', 'Intervention chirurgicale oto‑rhino‑laryngologique (adénoïdectomie, amygdalectomie, extractions dentaires),', 'Intervention chirurgicale gynécologique ou affections d’origine obstétricale,', 'Intervention chirurgicale thoracique et abdominale et autres interventions chirurgicales majeures telles qu’une chirurgie cardiovasculaire,', 'Prise en charge d’hémorragies dues à l’administration d’un agent fibrinolytique.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.,', 'Thrombose veineuse ou artérielle aiguë (voir rubrique 4.4),', 'Etats fibrinolytiques consécutifs à une coagulopathie de consommation, à l’exception d’états associés à une activation prédominante du système fibrinolytique avec une hémorragie grave aiguë (voir rubrique 4.4),', 'Insuffisance rénale grave (risque d''accumulation),', 'Antécédents de convulsions,', 'Injections intrathécales et intraventriculaires, applications intracérébrales (risque d''œdème cérébral et de convulsions).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Les indications et le mode d’administration décrits ci‑dessus doivent être strictement suivis :', 'les injections intraveineuses doivent être administrées très lentement', 'l’acide tranexamique ne doit pas être administré par voie intramusculaire.', 'Convulsions', 'Des cas de convulsions ont été rapportés en association avec un traitement par l’acide tranexamique.', 'Lors d’une chirurgie de pontage aortocoronarien (PAC), la plupart de ces cas ont été signalés après une injection intraveineuse (IV) d’acide tranexamique à des doses élevées.', 'Lorsque les doses plus faibles recommandées d’acide tranexamique étaient utilisées, l’incidence des crises post‑opératoires était similaire à celle constatée chez des patients non traités.', 'Troubles visuels', 'Il faut prêter attention aux troubles visuels possibles, notamment une déficience visuelle, une vision trouble, une perturbation de la vision des couleurs.', 'Si nécessaire, le traitement doit être interrompu.', 'Hématurie', 'En cas d’hématurie provenant des voies urinaires supérieures, il y a un risque d’obstruction urétrale.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Aucune étude d’interaction n’a été réalisée.', 'Un traitement simultané par des anticoagulants doit être administré sous la stricte surveillance d’un médecin spécialisé dans ce domaine.', 'Les médicaments qui agissent sur l’hémostase doivent être administrés avec précaution aux patients traités par l’acide tranexamique.', 'Il existe un risque théorique d’augmentation de la formation de thrombus, tel qu’avec les œstrogènes.', 'Par ailleurs, l’effet antifibrinolytique du médicament peut être antagonisé avec des thrombolytiques.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences ont été définies comme suit : très fréquent (≥ 1/10) ; fréquent (≥ 1/100 à', 'Peu fréquent']);

  -- peroxyde d (CIS 69609936)
  m := pg_temp.jp_matrice_by_norm('peroxyde d');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Préparations anti-acnéiques à usage topique, Rétinoïdes à usage topique dans l’acné, code ATC : D10AD53.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Ce médicament est indiqué dans le traitement cutané de l’acné vulgaire en présence de comédons, papules et pustules (voir rubrique 5.1).', 'Adapalène/peroxyde de benzoyle Bailleul 0,1 %/2,5 %, gel est indiqué chez les adultes, les adolescents et les enfants âgés de 9 ans et plus.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité aux substances actives ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Grossesse (voir rubrique 4.6).', 'Femmes planifiant une grossesse (voir rubrique 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['ADAPALENE/PEROXYDE DE BENZOYLE BAILLEUL ne doit pas être appliqué sur une peau lésée, abimée (coupures, écorchures), eczémateuse ou brûlée par le soleil.', 'ADAPALENE/PEROXYDE DE BENZOYLE BAILLEUL ne doit pas entrer en contact avec les yeux, la bouche, les narines ou les muqueuses.', 'En cas de contact avec les yeux, rincer immédiatement avec de l’eau tiède.', 'Si une réaction suggérant une sensibilité à l’un des composants apparaît, l’utilisation de ce médicament doit être interrompue.', 'L’exposition excessive au soleil ou aux lampes à ultraviolets doit être évitée.', 'ADAPALENE/PEROXYDE DE BENZOYLE BAILLEUL ne doit pas entrer en contact avec des matières colorées (cheveux ou fibres textiles teintés) en raison du risque de blanchiment et de décoloration.', 'Ce médicament contient 40 mg de propylèneglycol (E1520) par gramme de gel, ce qui équivaut à 4,00% p/p et peut causer une irritation de la peau.', 'Ce médicament contient des polysorbates qui peuvent provoquer des réactions allergiques.', 'Ce médicament peut contenir jusqu’à 2,5 mg d''acide benzoïque par gramme de gel, en tant que produit de dégradation du peroxyde de benzoyle.', 'L''acide benzoïque peut provoquer une irritation locale.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Aucune étude d’interaction n’a été réalisée.', 'D’après l’expérience acquise avec l’adapalène et le peroxyde de benzoyle, il n’existe aucune interaction connue avec d’autres médicaments topiques qui pourraient être utilisés simultanément avec ce gel.', 'Cependant, d’autres médicaments contenant des rétinoïdes, du peroxyde de benzoyle, ou ayant un mode d’action similaire ne doivent pas être utilisés de manière concomitante.', 'L’utilisation de produits cosmétiques desquamants, irritants ou desséchants doit être faite avec précaution, car elle peut entraîner une irritation supplémentaire avec ce médicament.', 'L’absorption d’adapalène à travers la peau humaine est faible (voir rubrique 5.2), en conséquence, une interaction avec un médicament pris par voie systémique est peu probable.', 'La pénétration percutanée du peroxyde de benzoyle est faible et la substance active est complètement métabolisée en acide benzoïque, qui est rapidement éliminé.', 'Par conséquent, une interaction potentielle de l’acide benzoïque avec des médicaments pris par voie systémique est très peu probable.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Réaction anaphylactique']);

  -- trinitrine (CIS 61245968)
  m := pg_temp.jp_matrice_by_norm('trinitrine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : vasodilatateur utilisé en cardiologie/dérivé nitré, code ATC : C01DA02 (Système cardio-vasculaire).');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement préventif de la crise d''angor.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament NE DOIT JAMAIS ETRE UTILISE dans les cas suivants :', 'hypersensibilité à la substance active ou aux dérivés nitrés ou à l’un des excipients mentionnés à la rubrique 6.1,', 'état de choc, hypotension sévère (pression artérielle systolique inférieure à 90 mm Hg),', 'hypovolémie sévère,', 'en association aux inhibiteurs de la phosphodiestérase 5 (PDE5) (voir rubriques 4.5 et 4.4):', 'o en cas de traitement par inhibiteurs de phosphodiestérase 5, les dérivés nitrés sont contre-indiqués sous quelque forme que ce soit.', 'En particulier, il convient d''avertir tout patient coronarien de ce que, s''il présente au cours de l''acte sexuel des douleurs angineuses, il ne devra en aucun cas prendre un dérivé nitré d''action immédiate.', 'o en cas de traitement par le riociguat, en raison du risque d’hypotension importante (effet synergique) (voir rubrique 4.5).', 'Ce médicament NE DOIT GENERALEMENT PAS ETRE UTILISE en cas de :', 'insuffisance cardiaque obstructive (par exemple, en présence d’une sténose mitrale ou aortique ou d’une péricardite constrictive),', 'infarctus du myocarde de siège inférieur avec extension au ventricule droit, à la phase aiguë,', 'hypertension intracrânienne,']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'En cas de survenue d''un collapsus ou d''un état de choc, retirer le dispositif (voir rubrique 4.3).', 'En cas d’infarctus du myocarde ou d’insuffisance cardiaque aiguë récents, le traitement par TRINITRINE VIATRIS doit être débuté avec prudence, sous contrôle médical strict et/ou surveillance hémodynamique.', 'Le dispositif doit être enlevé avant de réaliser un choc électrique externe ou un traitement par diathermie.', 'Le retrait du dispositif transdermique doit être considéré comme une partie intégrante de la prise en charge des patients présentant une hypotension importante.', 'Association de dérivés nitrés aux inhibiteurs de la phosphodiestérase 5 (PDE5) :', 'L''utilisation de produits topiques, en particulier en cas d''utilisation prolongée, peut entraîner des phénomènes de sensibilisation.', 'Dans ce cas, le traitement devra être suspendu et des mesures thérapeutiques appropriées devront être mises en œuvre.', 'Précautions d''emploi', 'Les substances vasodilatatrices, antihypertensives, les diurétiques, et l''alcool, peuvent majorer l''hypotension provoquée par les dérivés nitrés, surtout chez les personnes âgées.', 'Il n''est pas logique d''associer la trinitrine avec la molsidomine ou le nicorandil dans la mesure où leur mécanisme d''action est similaire.', 'Hypoxémie']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'Inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil ou autre)', 'Risque d''hypotension importante (effet synergique) pouvant aggraver l''état d''ischémie myocardique et provoquer notamment un accident coronarien aigu.', 'Riociguat', 'Risque d''hypotension importante (effet synergique).', 'L’utilisation concomitante de TRINITRINE VIATRIS avec le riociguat, un stimulateur de la guanylate cyclase soluble, est contre indiquée (voir rubrique 4.3), puisqu’elle peut provoquer une hypotension.', 'Associations à prendre en compte', 'Inhibiteurs calciques, Inhibiteurs de l’enzyme de conversion, bêtabloquants, diurétiques, antihypertenseurs, antidépresseurs tricycliques, neuroleptiques, principaux psychotropes', 'Risque d’hypotension importante.', 'Dihydroergotamine', 'Augmentation de la biodisponibilité de la dihydroergotamine.', 'Une attention particulière est requise chez les patients présentant une coronaropathie, car la dihydroergotamine s’oppose à l’effet de la trinitrine et peut induire une vasoconstriction coronaire.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥ 1/10) ;', 'Fréquent (≥ 1/100, Peu fréquent (≥ 1/1 000, Rare (≥ 1/10 000, Très rare (Indéterminée (ne peut être estimé à partir des données disponibles)', 'Fréquent : céphalées1']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['En cas d’infarctus du myocarde ou d’insuffisance cardiaque aiguë récents, le traitement par TRINITRINE VIATRIS doit être débuté avec prudence, sous contrôle médical strict et/ou surveillance hémodynamique.']);

  -- isosorbide dinitrate (CIS 60172339)
  m := pg_temp.jp_matrice_by_norm('isosorbide dinitrate');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : VASODILATATEUR UTILISE EN CARDIOLOGIE / DERIVE NITRE, code ATC : C01DA08 : système cardiovasculaire.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement curatif de la crise d''angor.', 'Traitement préventif à très court terme (ou précritique) de la crise d''angor.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit jamais être utilisé en cas de :', 'hypersensibilité à la substance active, aux dérivés nitrés ou à l’un des excipients mentionnés à la rubrique 6.1,', 'état de choc, hypotension sévère,', 'en association au sildénafil (voir les rubriques 4.5 et 4.4) :', 'o chez tout patient traité par dérivé nitré, sous quelque forme que ce soit, on ne doit pas prescrire de sildénafil tant que le patient est sous l''action du dérivé nitré.', 'o en cas de traitement par sildénafil, les dérivés nitrés sont contre-indiqués sous quelque forme que ce soit.', 'En particulier, il convient d''avertir tout patient coronarien de ce que, s''il présente au cours de l''acte sexuel des douleurs angineuses, il ne devra en aucun cas prendre un dérivé nitré d''action immédiate.', 'Ce médicament ne doit généralement pas être utilisé en cas de :', 'cardiomyopathie obstructive,', 'infarctus du myocarde de siège inférieur avec extension au ventricule droit, à la phase aiguë, sauf en cas de signe d''insuffisance ventriculaire gauche,', 'hypertension intra-crânienne', 'allaitement.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Association de dérivés nitrés au sildénafil', 'Précautions d''emploi', 'Les substances vasodilatatrices, antihypertensives, les diurétiques et l''alcool peuvent majorer l''hypotension provoquée par les dérivés nitrés, surtout chez le sujet âgé.', 'Ce médicament contient de petites quantités d''éthanol (alcool), inférieures à 100 mg par dose.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', '+ Sildénafil', 'Risque d''hypotension importante (effet synergique) pouvant aggraver l''état d''ischémie myocardique et provoquer notamment un accident coronarien aigu.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Céphalées dose-dépendantes.', 'Hypotension artérielle, parfois orthostatique, surtout rapportée chez le sujet âgé ou lors d''association à d''autres vasodilatateurs.', 'Ces hypotensions peuvent être associées à une tachycardie réflexe et s''accompagner de sensations vertigineuses, de lipothymies, ou exceptionnellement de syncopes.', 'Vasodilatation cutanée avec érythème et bouffées de chaleur.', 'Troubles digestifs (nausées, vomissements).', 'Déclaration des effets indésirables suspectés']);

  -- molsidomine (CIS 60740076)
  m := pg_temp.jp_matrice_by_norm('molsidomine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : AUTRES VASODILATATEURS EN CARDIOLOGIE, code ATC : C01DX12 (C : système cardiovasculaire)');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement préventif de la crise angineuse sous toutes ses formes.', 'Les comprimés de MOLSIDOMINE ARROW ne sont pas adaptés au traitement de la crise d''angor.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit pas être prescrit dans les cas suivants :', 'Hypersensibilité à la molsidomine ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Hypotension marquée avec état de choc.', 'Association aux inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil) (voir rubriques 4.4 et 4.5) :', 'o chez tout patient traité par la molsidomine on ne doit pas prescrire d’inhibiteurs de la phosphodiestérase de type 5 tant que le patient est sous l’action de la molsidomine.', 'o en cas de traitement par les inhibiteurs de la phosphodiestérase de type 5, la molsidomine est contre-indiquée.', 'Ce médicament est généralement déconseillé en cas d''allaitement (voir rubrique 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Association de la molsidomine aux inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil) :', 'Excipients', 'Ce médicament contient du lactose.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.', 'Précautions d’emploi', 'Une légère baisse de la pression artérielle est habituelle sous molsidomine.', 'Une posologie progressive est recommandée en cas d’insuffisance hépatocellulaire.', 'Dénuée de tout effet dépresseur myocardique, la molsidomine peut être associée aux bêta-bloquants.', 'Elle est dépourvue d’effet sur le tissu de conduction.', 'La substitution aux dérivés nitrés retard est plus logique que l’association, en raison d’une action commune sur la précharge.', 'Il n''est pas logique d''associer la molsidomine avec les dérivés nitrés d''action prolongée dans la mesure où leur mécanisme d''action est similaire.', 'Alcaloïdes de l’ergot de seigle : Une interaction pharmacodynamique (effet antagoniste), entre les donneurs de monoxyde d’azote (NO) et les alcaloïdes de l’ergot de seigle est possible.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', '+ Inhibiteurs de la phosphodiestérase de type 5 (sildénafil, tadalafil, vardénafil)', 'Risque d’hypotention importante (effet synergique) pouvant aggraver l’état d’ischémie myocardique et provoquer notamment un accident coronarien aigu.', '+ Riociguat', 'Risque d’hypotension importante (effet synergique)', 'Associations faisant l''objet de précautions d’emploi', 'En effet, les effets hypotensifs peuvent être majorés.', 'Associations à prendre en compte', '+ Dapoxétine', 'Risque de majoration des effets indésirables, notamment à type de vertiges ou de syncopes.', '+ Médicaments abaissant la pression artérielle', 'Majoration du risque d’hypotension, notamment orthostatique.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Des céphalées habituellement modérées et une légère baisse tensionnelle peuvent apparaître en début de traitement.', 'Les céphalées régressent en général spontanément en quelques jours.', 'Ces effets peuvent être majorés par la prise simultanée d’autres vasodilatateurs.', 'Une posologie progressive permet d’en réduire la fréquence.', 'Exceptionnellement, ont été signalés une hypotension orthostatique, des troubles digestifs, des vertiges ou un prurit.', 'De rares cas de thrombopénie ont été rapportés.']);

  -- nicorandil (CIS 66925249)
  m := pg_temp.jp_matrice_by_norm('nicorandil');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : autres vasodilatateurs en cardiologie, code ATC : C01DX16.');
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'choc (notamment choc cardiogénique), hypotension sévère, ou dysfonction ventriculaire gauche associée à une faible pression de remplissage ou à une décompensation cardiaque ;', 'utilisation d’inhibiteurs de la phosphodiestérase 5, car ceux-ci sont susceptibles d’entraîner une baisse importante de la pression artérielle (voir rubrique 4.5) ;', 'utilisation de stimulateur(s) de la guanylate cyclase soluble (tels que le riociguat), car ceux-ci sont susceptibles d’entraîner une baisse importante de la pression artérielle (voir rubrique 4.5) ;', 'hypovolémie ;', 'œdème aigu du poumon.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Ulcérations', 'Des ulcérations gastro-intestinales, de la peau et des muqueuses ont été rapportées avec le nicorandil (voir rubrique 4.8).', 'Ulcérations gastro-intestinales', 'Des ulcérations à différents endroits du corps induites par le nicorandil peuvent survenir chez le même patient.', 'Elles sont réfractaires au traitement et, dans la plupart des cas, répondent uniquement à l’arrêt du traitement par nicorandil.', 'Si une ou plusieurs ulcération(s) apparaisse(nt), il convient d’arrêter définitivement le nicorandil (voir rubrique 4.8).', 'Les professionnels de santé doivent être avertis de l’importance du diagnostic rapide des ulcérations induites par le nicorandil et de l’arrêt rapide du traitement par nicorandil en cas d’ulcérations.', 'Sur la base des données disponibles, l’apparition des ulcérations peut intervenir peu après l’instauration du traitement par nicorandil mais également jusqu’à plusieurs années après le début du traitement par nicorandil.', 'Des hémorragies gastro-intestinales secondaires à une ulcération gastro-intestinale ont été rapportées avec le nicorandil.', 'La prudence est donc de rigueur lorsque l’utilisation concomitante d’acide acétylsalicylique ou d’AINS avec du nicorandil est envisagée (voir rubrique 4.5).', 'A un stade avancé, les ulcérations gastro-intestinales peuvent évoluer en perforation, formation de fistule ou d’abcès.', 'Les patients souffrant de maladie diverticulaire présentent un risque particulier de formation de fistule ou de perforation intestinale durant le traitement par nicorandil.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L’utilisation concomitante d’un stimulateur de la guanylate cyclase soluble (tel que le riociguat) est contre-indiquée car elle peut entraîner une baisse importante de la pression artérielle.', 'Aux doses thérapeutiques, le nicorandil peut avoir un effet hypotenseur.', 'La dapoxétine doit être prescrite avec prudence chez les patients sous nicorandil en raison d’une diminution possible de la tolérance orthostatique.', 'Des perforations gastro-intestinales ont été rapportées lors de l’utilisation concomitante de nicorandil avec des corticoïdes.', 'La prudence est de rigueur lorsqu’une utilisation concomitante est envisagée.', 'La prudence est recommandée lorsque le nicorandil est associé avec d’autres médicaments susceptibles d’augmenter le taux de potassium (voir rubriques 4.4 et 4.8).', 'Le métabolisme du nicorandil n’est pas significativement affecté par la cimétidine (un inhibiteur du CYP) ou la rifampicine (un inducteur du CYP3A4).', 'Le nicorandil n’affecte pas la pharmacodynamique de l’acénocoumarol.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences sont définies comme suit : Très fréquent (≥1/10), Fréquent (≥1/100,', 'Très fréquent', 'Fréquent', 'Peu fréquent']);

  -- nifedipine (CIS 66932763)
  m := pg_temp.jp_matrice_by_norm('nifedipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : INHIBITEURS CALCIQUES SELECTIFS A EFFETS VASCULAIRES, code ATC : C08CA05.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle.', 'Traitement préventif de l’angor stable, en association avec un traitement bêétabloquant.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit pas être utilisé dans les cas suivants :', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1', 'Infarctus du myocarde datant de moins de 1 mois', 'Angor instable (voir rubrique 4.4)', 'choc cardio-vasculaire (voir rubrique 4.4)', 'en association avec le diltiazem (voir rubrique 4.5)', 'en association avec la rifampicine, car les taux plasmatiques efficaces de la nifédipine pourraient ne pas être atteints en raison d’une induction enzymatique (voir rubrique 4.5)', 'chez les patients ayant subi une iléostomie après procto-colectomie.', 'Ce médicament est généralement déconseillé pendant la grossesse ou l’allaitement (voir rubrique 4.6)']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'La prise de ce médicament avec la ciclosporine ou le dantrolène administré par perfusion est déconseillée (voir rubrique 4.5).', 'La nifédipine ne doit pas être utilisée pendant la grossesse sauf si l''état clinique de la patiente le nécessite.', 'La nifédipine doit être réservée aux femmes ayant une hypertension sévère et qui ne répondent pas aux traitements standards (voir rubrique 4.6).', 'Association aux bêtabloquants : chez le coronarien, l''instauration du traitement par ce médicament requiert un traitement concomitant par bêtabloquant à dose efficace.', 'Elle se fera sous surveillance médicale particulière, chez les sujets en insuffisance cardiaque latente (voir rubrique 4.5).', 'La nifédipine n''affecte pas la conduction cardiaque.', 'Cependant, par référence aux autres antagonistes calciques, la prudence s''impose en cas de dysfonctionnement sinusal et d''anomalie de la conduction.', 'Chez les patients présentant une insuffisance hépatique légère, modérée ou sévère, une surveillance étroite ainsi qu’une réduction de la dose peuvent être nécessaires.', 'Les paramètres pharmacocinétiques de la nifédipine n''ont pas été étudiés chez les patients présentant une insuffisance hépatique sévère (voir rubriques 4.2 et 5.2).', 'Par conséquent, la nifédipine doit être utilisée avec prudence chez les patients présentant une insuffisance hépatique sévère.', 'La nifédipine est métabolisée via le système du cytochrome P450 3A4.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La nifédipine est métabolisée par l’isoenzyme 3A4 du cytochrome P450, localisé dans la muqueuse intestinale et dans le foie.', 'Les médicaments connus pour inhiber ou induire ce système enzymatique peuvent donc influencer l’effet de premier passage hépatique (après administration orale) ou la clairance de la nifédipine (voir rubrique 4.4).', 'Il convient de tenir compte de l’ampleur et de la durée des interactions lorsque la nifédipine est administrée avec les médicaments suivants.', 'Associations contre-indiquées', '+ Rifampicine', 'La rifampicine est un inducteur puissant du système du cytochrome P450 3A4.', 'Lors d’administration concomitante avec la rifampicine, la biodisponibilité de la nifédipine est clairement réduite et son efficacité est donc amoindrie.', 'L’utilisation de nifédipine en association avec la rifampicine est dès lors contre-indiquée (voir rubrique 4.3).', 'Une surveillance clinique et une adaptation éventuelle de la posologie après l’arrêt du traitement par la rifampicine devront être envisagées.', '+ Diltiazem', 'Augmentation importante des concentrations de nifédipine par diminution de son métabolisme hépatique par le diltiazem, avec risque d’hypotension sévère.', 'Associations déconseillées']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables considérés comme « fréquents » ont été observés avec une incidence inférieure à 3%, à l’exception des oedèmes (9,9%) et des céphalées (3,9%).', 'Fréquent', 'Peu fréquent', 'Agranulocytose']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Elle se fera sous surveillance médicale particulière, chez les sujets en insuffisance cardiaque latente (voir rubrique 4.5).', 'Chez les patients présentant une insuffisance hépatique légère, modérée ou sévère, une surveillance étroite ainsi qu’une réduction de la dose peuvent être nécessaires.']);

  -- nicardipine (CIS 67962026)
  m := pg_temp.jp_matrice_by_norm('nicardipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : INHIBITEURS CALCIQUES SELECTIFS A EFFETS VASCULAIRES');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['La nicardipine par voie intraveineuse est indiquée dans l’urgence hypertensive menaçant le pronostic vital, en particulier en cas de :', 'Hypertension artérielle maligne/Encéphalopathie hypertensive,', 'Dissection aortique, quand le traitement par des bêta-bloquants à courte durée d’action n’est pas approprié, ou en association avec un bêta-bloquant quand le blocage des récepteurs bêta seul n’est pas efficace,', 'Pré-éclampsie sévère, quand d’autres agents antihypertenseurs administrés par voie intraveineuse ne sont pas recommandés ou sont contre-indiqués.', 'La nicardipine est également indiquée dans le traitement de l’hypertension post-opératoire.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'Sténose aortique sévère,', 'Hypertension compensatoire, en cas de shunt artérioveineux ou de coarctation de l’aorte,', 'Angor instable,', 'Dans les 8 jours après un infarctus du myocarde.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'Il est recommandé d’administrer la nicardipine avec précaution pour éviter une chute excessive de la pression artérielle.', 'En effet, des réductions pharmacologiques rapides de la pression artérielle peuvent entraîner une hypotension systémique et une tachycardie réflexe.', 'Si l’un de ces deux effets apparaît sous nicardipine, il peut être nécessaire de diminuer la dose de moitié ou d’arrêter la perfusion.', 'Insuffisance cardiaque', 'Maladie cardiovasculaire ischémique', 'La nicardipine est contre-indiquée dans l’angor instable et dans les suites immédiates d’un infarctus du myocarde (voir rubrique 4.3).', 'La nicardipine doit être utilisée avec précautions chez les patients pour lesquels une ischémie coronarienne est suspectée.', 'Occasionnellement, des patients ont développé une augmentation de la fréquence, de la durée ou de la sévérité de l’angor à l’initiation ou lors d’augmentation des doses de nicardipine, ou au cours du traitement.', 'Grossesse', 'En raison du risque d’hypotension maternelle sévère et d’hypoxie fœtale potentiellement fatale, la diminution de la pression artérielle doit être progressive et toujours étroitement surveillée.', 'En raison du risque potentiel d’œdème pulmonaire ou d’une diminution excessive de la pression artérielle, des précautions doivent être prises en cas d’administration concomitante de sulfate de magnésium.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', 'Dantrolène', 'Avec le dantrolène administré par perfusion :', 'Dans des études chez l’animal, des cas de fibrillations ventriculaires mortelles sont constamment observées lors de l’administration de vérapamil et de dantrolène par voie intraveineuse.', 'L’association d’un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.', 'Cependant, quelques patients ont reçu l’association nifédipine et dantrolène sans inconvénient.', 'Associations faisant l''objet de précautions d’emploi', 'Idélalisib', 'Majoration des effets indésirables de la nicardipine, à type d’hypotension orthostatique, notamment chez le sujet âgé.', 'Surveillance clinique et adaptation de la posologie de la nicardipine pendant le traitement par l’idélalisib et après son arrêt.', 'Immunosuppresseurs (ciclosporine, everolimus, sirolimus, tacrolimus, temsirolimus)', 'Augmentation des concentrations sanguines de l’immunosuppresseur, par inhibition de son métabolisme.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets les plus fréquents sont des céphalées, des vertiges, des œdèmes périphériques, des palpitations et des bouffées congestives.', 'Les catégories de fréquence sont définies selon la convention suivante : très fréquent (≥ 1/10), fréquent (≥ 1/100 à', 'Fréquence indéterminée – réaction anaphylactique']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['En raison du risque d’hypotension maternelle sévère et d’hypoxie fœtale potentiellement fatale, la diminution de la pression artérielle doit être progressive et toujours étroitement surveillée.']);

  -- nitrendipine (CIS 67688899)
  m := pg_temp.jp_matrice_by_norm('nitrendipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs calciques sélectifs à effets vasculaires, code ATC : C08CA08.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l''hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament est contre-indiqué :', 'en cas d’hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'en cas d’angor instable ou dans les 4 semaines suivant un infarctus du myocarde aigu,', 'pendant la grossesse et l’allaitement (voir rubrique 4.6),', 'en association avec la rifampicine.', 'Par conséquent, l’administration concomitante de rifampicine est contre-indiquée (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mise en garde', 'Insuffisance cardiaque décompensée', 'Les patients souffrant d’une insuffisance cardiaque décompensée doivent être traités avec précaution.', 'Troubles hépatiques', 'Chez les patients présentant des troubles hépatiques sévères, les effets de la nitrendipine peuvent être renforcés et prolongés.', 'Dans ce cas, les patients doivent être étroitement surveillés par un contrôle fréquent de leur pression artérielle au cours du traitement (voir rubriques 4.2 et 5.2).', 'Comme avec d’autres substances vasoactives, un angor peut survenir de façon très rare avec la nitrendipine, en particulier au début du traitement (données issues de la notification spontanée).', 'Les données issues des études cliniques confirment que la survenue de cet angor est peu fréquente (voir rubrique 4.8).', 'Ce médicament ne doit généralement pas être utilisé :', 'en cas d’association au dantrolène (perfusion) (voir rubrique 4.5).', 'Cytochrome CYP 3A4', 'La nitrendipine est métabolisée par le cytochrome CYP3A4.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La nitrendipine est métabolisée par le cytochrome CYP3A4, situé dans la muqueuse intestinale et le foie.', 'Les médicaments connus pour inhiber ou stimuler ce système enzymatique peuvent donc modifier le métabolisme de premier passage ou la clairance de la nitrendipine.', 'L’importance et la durée de l''interaction doivent être prises en compte lors de l''administration concomitante de la nitrendipine avec de tels médicaments.', 'Associations contre-indiquées', '+ Rifampicine', 'L’efficacité de la nitrendipine pourrait donc être diminuée en cas d’administration concomitante avec la rifampicine.', 'L’utilisation de la nitrendipine en association à la rifampicine est en conséquence contre-indiquée (voir rubrique 4.3).', 'En cas d’administration concomitante avec les inhibiteurs du cytochrome CYP3A4, il convient de surveiller la tension artérielle et d’envisager éventuellement une diminution de la dose de nitrendipine.', 'Associations déconseillées', '+ Dantrolène (administré par perfusion)', 'Chez l''animal, des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l''administration de vérapamil et de dantrolène par voie IV.', 'L''association d''un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥ 1/10),', 'Fréquent (≥ 1/100 à', 'Peu fréquent (≥ 1/1 000 à']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Dans ce cas, les patients doivent être étroitement surveillés par un contrôle fréquent de leur pression artérielle au cours du traitement (voir rubriques 4.2 et 5.2).']);

  -- isradipine (CIS 67966754)
  m := pg_temp.jp_matrice_by_norm('isradipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : INHIBITEURS DES CANAUX CALCIQUES SÉLECTIFS VASCULAIRES, code ATC : C08CA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l’hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité connue à l’isradipine, aux autres inhibiteurs des canaux calciques de la famille des dihydropyridines ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Comme avec les autres inhibiteurs des canaux calciques, ICAZ LP 2,5 mg, gélule ne doit pas être utilisé chez les patients présentant les conditions suivantes :', 'Choc cardiogénique,', 'Angor instable,', 'Infarctus du myocarde datant de moins d’un mois.', 'Enfant : l''absence de données cliniques contre-indique l''utilisation de ce produit chez l''enfant.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Il est recommandé d’adapter la posologie chez les personnes âgées, et les insuffisants hépatiques (voir rubrique 4.2).', 'Il est recommandé d’adapter la posologie avec prudence chez les insuffisants rénaux et les insuffisants cardiaques chroniques.', 'Des précautions doivent être prises chez les patients ayant une maladie du nœud sinusal confirmée ou fortement suspectée et qui ne sont pas appareillés avec un pacemaker.', 'Prendre des précautions particulières en cas de faible pression systolique ou de sténose aortique sévère.', 'Une crise angineuse peut survenir principalement chez des patients présentant une cardiopathie ischémique.', 'Lors de l’initiation du traitement ou lors de l’augmentation trop rapide de la posologie chez ces patients, la fréquence, la durée et la sévérité des crises angineuses peuvent se majorer.', 'ICAZ LP 2,5 mg, gélule doit être arrêté en cas de réaction d’hypersensibilité à ce médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', 'Dantrolène', 'Avec le dantrolène administré par perfusion : chez l''animal, des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l''administration de vérapamil et de dantrolène IV.', 'L''association d''un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.', 'Cependant, quelques patients ont reçu l''association nifédipine et dantrolène sans inconvénient.', 'Associations faisant l''objet de précautions d’emploi', 'Itraconazole, kétoconazole', 'Risque majoré d''effets indésirables, notamment d’œdèmes, par diminution du métabolisme hépatique de la dihydropyridine.', 'Surveillance clinique et adaptation éventuelle de la posologie de la dihydropyridine pendant le traitement par l’itraconazole ou le kétoconazole et après leur arrêt.', 'Anticonvulsivants inducteurs enzymatiques (carbamazepine, fosphenytoine, phénobarbital, phenytoine, primidone, etc.)', 'Diminution des concentrations plasmatiques de l''antagoniste du calcium par augmentation de son métabolisme hépatique par l’inducteur.', 'Surveillance clinique et adaptation éventuelle de la posologie de l''antagoniste du calcium pendant le traitement par l''inducteur et après son arrêt.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquentes : céphalées', 'Fréquentes : sensations vertigineuses', 'Fréquentes : tachycardie, palpitations']);

  -- amlodipine (CIS 69622809)
  m := pg_temp.jp_matrice_by_norm('amlodipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs calciques sélectifs à principalement effet vasculaire, code ATC : C08CA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension.', 'Angor chronique stable.', 'Angor vasospastique (syndrome de Prinzmetal).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['L’amlodipine est contre-indiquée chez les patients présentant :', 'une hypersensibilité à l’amlodipine, aux dérivés de la dihydropyridine ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'une hypotension sévère ;', 'un choc (y compris choc cardiogénique) ;', 'une obstruction de la voie d’éjection du ventricule gauche (par exemple, sténose aortique de degré élevé) ;', 'une insuffisance cardiaque hémodynamiquement instable après un infarctus aigu du myocarde.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['La sécurité d’emploi et l’efficacité de l’amlodipine au cours d’une crise hypertensive n’ont pas été établies.', 'Patients atteints d’insuffisance cardiaque', 'Les patients atteints d’insuffisance cardiaque doivent être traités avec précaution.', 'Patients atteints d’insuffisance hépatique', 'La demi-vie de l’amlodipine est augmentée et son ASC (Aire Sous la Courbe) est plus grande chez les patients atteints d’insuffisance hépatique ; les recommandations posologiques n’ont pas été établies.', 'Par conséquent l’amlodipine devra être initiée à la dose efficace la plus faible et avec précaution, aussi bien durant l’initiation du traitement que lors de l’augmentation de la dose.', 'Une augmentation posologique lente et une surveillance attentive peuvent être nécessaires chez les patients avec une insuffisance hépatique sévère.', 'Patients âgés', 'Chez les sujets âgés, une augmentation de la posologie doit être effectuée avec précaution (voir rubriques 4.2 et 5.2).', 'Patients atteints d’insuffisance rénale', 'L’amlodipine peut être utilisée chez ces patients à des doses normales.', 'Les changements des concentrations plasmatiques d’amlodipine ne sont pas corrélés avec le degré d’insuffisance rénale.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Effets des autres médicaments sur l’amlodipine', '+ Inhibiteurs du CYP3A4', 'La traduction clinique de ces variations pharmacocinétiques peut être plus prononcée chez le sujet âgé.', 'Par conséquent, une surveillance clinique et un ajustement de la dose pourront être nécessaires.', '+ Inducteurs du CYP3A4', 'Lors de la co-administration d’inducteurs connus du CYP3A4, la concentration plasmatique d’amlodipine peut varier.', '+ Dantrolène (perfusion)', 'Chez l’animal, une fibrillation ventriculaire et un collapsus cardiovasculaire létaux ont été observés en association avec une hyperkaliémie après l’administration de vérapamil et de dantrolène IV.', 'Effets de l’amlodipine sur d’autres médicaments', 'Les effets hypotenseurs de l’amlodipine s’ajoutent à ceux d’autres médicaments présentant des propriétés antihypertensives.', '+ Tacrolimus', '+ Inhibiteurs de la cible mécanique de la rapamycine (mTOR)']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Leucocytopénie, thrombocytopénie']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Une augmentation posologique lente et une surveillance attentive peuvent être nécessaires chez les patients avec une insuffisance hépatique sévère.']);

  -- felodipine (CIS 69451322)
  m := pg_temp.jp_matrice_by_norm('felodipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteur calcique, dérivés de la dihydropyridine, code ATC : C08CA02.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle,', 'Angor stable.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Grossesse,', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'Insuffisance cardiaque décompensée,', 'Infarctus du myocarde aigu,', 'Angor instable,', 'Sténose valvulaire cardiaque hémodynamiquement significative,', 'Obstruction des voies d’éjection cardiaque.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['L’efficacité et la sécurité d’emploi de la félodipine dans le traitement des urgences hypertensives n’ont pas été étudiées.', 'La félodipine peut entraîner une hypotension significative suivie d''une tachycardie.', 'Cela peut conduire à une ischémie myocardique chez les patients prédisposés.', 'La félodipine est éliminée par le foie.', 'Par conséquent, des concentrations thérapeutiques et une réponse plus importantes peuvent être attendues chez les patients avec une altération de la fonction hépatique (voir rubrique 4.2).', 'L’administration concomitante de médicaments qui induisent ou inhibent fortement les enzymes du CYP3A4 résulte respectivement en la forte diminution ou augmentation des concentrations plasmatiques de félodipine.', 'Par conséquent, de telles associations doivent donc être évitées (voir rubrique 4.5).', 'Ce médicament contient du lactose.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.', 'Ce médicament contient moins de 1 mmol (23 mg) de sodium par comprimé, c’est-à-dire qu’il est essentiellement « sans sodium ».', 'Une légère hypertrophie gingivale a été observée chez des patients atteints d''une gingivite/parodontite prononcée.', 'L’hypertrophie peut être évitée ou disparaître avec une hygiène dentaire soignée.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La félodipine est métabolisée dans le foie par le cytochrome P450 3A4 (CYP3A4).', 'L''administration concomitante de substances qui interfèrent avec le système enzymatique CYP3A4 peut affecter les concentrations plasmatiques de félodipine.', 'Interactions enzymatiques', 'Les substances inhibitrices enzymatiques et inductrices enzymatiques de l''isoenzyme 3A4 du cytochrome P450 peuvent exercer une influence sur la concentration plasmatique de félodipine.', 'Interactions entraînant une augmentation de la concentration plasmatique de félodipine', 'Il a été montré que les inhibiteurs enzymatiques du CYP3A4 entraînent une augmentation des concentrations plasmatiques de félodipine.', 'La Cmax et l''ASC de la félodipine ont augmenté respectivement de 8 fois et de 6 fois lorsque la félodipine a été co-administrée avec de l’itraconazole, un inhibiteur puissant du CYP3A4.', 'Lorsque la félodipine et l''érythromycine ont été co-administrées, la Cmax et l''ASC de la félodipine ont augmenté d''environ 2,5 fois.', 'La cimétidine a augmenté la Cmax et l''ASC de la félodipine d''environ 55 %.', 'L’association avec des inhibiteurs puissants du CYP3A4 doit être évitée.', 'Exemples :', 'Cimétidine,']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent ≥ 1/10']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Par conséquent, des concentrations thérapeutiques et une réponse plus importantes peuvent être attendues chez les patients avec une altération de la fonction hépatique (voir rubrique 4.2).']);

  -- manidipine (CIS 67302931)
  m := pg_temp.jp_matrice_by_norm('manidipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs calciques sélectifs à effets vasculaires prédominants, code ATC : C08CA11.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle essentielle légère à modérée.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active, à tout autre produit de la famille des dihydropyridines ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Chez l''enfant.', 'Angor instable ou infarctus du myocarde récent (au cours des 4 premières semaines après l''infarctus).', 'Insuffisance cardiaque non traitée.', 'Insuffisance rénale sévère (clairance de la créatinine', 'Insuffisance hépatique modérée à sévère.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Le produit doit être administré avec prudence chez les patients atteints d''insuffisance hépatique légère, car son effet antihypertenseur peut être majoré chez ce type de patients (voir rubrique 4.2).', 'En raison du ralentissement des processus métaboliques, un ajustement de la posologie est nécessaire chez les sujets âgés (voir rubrique 4.2).', 'En l''absence de données cliniques chez des patients atteints de coronaropathie stable, la prudence est requise chez ce type de patients en raison d''une éventuelle majoration du risque coronarien (voir rubrique 4.8).', 'Dialyse péritonéale', 'La manidipine a été associée au développement d’un effluent péritonéal trouble chez des patients sous dialyse péritonéale.', 'La turbidité est due à une augmentation de la concentration en triglycérides dans l’effluent péritonéal et tend à se résorber après l’arrêt du traitement par manidipine.', 'Excipient', 'MANIDIPINE ARROW contient du lactose monohydraté.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L''effet antihypertenseur de la manidipine peut être majoré par l''administration concomitante de diurétiques, de bêtabloquants et, en règle générale, de tout autre antihypertenseur.', 'Les études in vitro montrent que le potentiel d''inhibition du cytochrome P450 par la manidipine ne semble pas cliniquement significatif.', 'Comme pour les autres antagonistes calciques de la famille des dihydropyridines, l''isoenzyme P4503A4 joue vraisemblablement un rôle de catalyseur dans le métabolisme de la manidipine.', 'De plus, l''administration simultanée d''un antagoniste calcique et de digoxine peut entraîner une augmentation des concentrations du glucoside.', 'Alcool : comme avec tous les antihypertenseurs vasodilatateurs, la prudence est de rigueur en cas de consommation concomitante d''alcool, qui est susceptible de potentialiser leurs effets.', 'En conséquence, MANIDIPINE ARROW et le jus de pamplemousse ne devront pas être pris simultanément.', 'Aucune interaction n''a été observée avec les hypoglycémiants oraux.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables les plus fréquents (≥ 1 % et Ils sont dose-dépendants et disparaissent, le plus souvent, spontanément lors de la poursuite du traitement.', 'Très fréquent ≥ 1/10', 'Fréquent ≥ 1/100 et Peu fréquent ≥ 1/1 000 et Rare ≥ 1/10 000 et Très rare Fréquence indéterminée : ne peut être estimée sur la base des données disponibles.', 'Fréquent', 'Peu fréquent']);

  -- lercanidipine (CIS 60171874)
  m := pg_temp.jp_matrice_by_norm('lercanidipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Inhibiteur calcique sélectif à effets vasculaires prédominants - Dérivés de la dihydropyridine, code ATC : C08CA13.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['LERCANIDIPINE ACCORD est indiqué dans le traitement de l''hypertension essentielle légère à modérée.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Obstacle à l’éjection du ventricule gauche.', 'Insuffisance cardiaque congestive non traitée.', 'Angor instable ou infarctus du myocarde datant de moins d’un mois.', 'Insuffisance hépatique sévère.', 'Insuffisance rénale sévère (DFG', 'En association avec :', 'o inhibiteurs puissants du CYP3A4 (voir rubrique 4.5) ;', 'o ciclosporine (voir rubrique 4.5) ;', 'o pamplemousse ou jus de pamplemousse (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Maladie sinusale', 'La lercanidipine doit être administrée avec prudence chez les patients présentant une dysfonction du nœud sinusal (lorsqu’un stimulateur cardiaque n’a pas été installé).', 'Dysfonction ventriculaire gauche', 'Même si des études hémodynamiques contrôlées n’ont révélé aucune altération de la fonction ventriculaire, des précautions doivent être prises chez des patients ayant une dysfonction ventriculaire gauche.', 'Cardiopathie ischémique', 'Les données suggèrent que les patients atteints de cardiopathie ischémique présentent un risque cardiovasculaire élevé sous traitement par certaines dihydropyridines à courte durée d’action.', 'Bien que la lercanidipine possède une longue durée d’action, la prudence est recommandée chez ces patients.', 'Dans de rares cas, certaines dihydropyridines peuvent entraîner des douleurs précordiales ou un angor.', 'Dans de très rares cas, des patients ayant un angor préexistant peuvent présenter une augmentation de la fréquence, de la durée ou de la gravité des crises angineuses.', 'Des cas isolés d’infarctus du myocarde peuvent être observés (voir rubrique 4.8).', 'Utilisation en cas d''insuffisance rénale ou hépatique', 'Une prudence particulière doit être exercée au début du traitement chez les patients présentant une insuffisance rénale légère à modérée.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'Inhibiteurs du cytochrome CYP3A4', 'La lercanidipine est métabolisée par l’enzyme CYP3A4 et, par conséquent, les inhibiteurs du cytochrome CYP3A4 administrés simultanément peuvent interagir avec le métabolisme et l’élimination de la lercanidipine.', 'L’administration de lercanidipine avec des inhibiteurs du CYP3A4 (par exemple kétoconazole, itraconazole, ritonavir, érythromycine, troléandomycine, clarithromycine) doit être évitée (voir rubrique 4.3).', 'Ciclosporine', 'Une élévation des concentrations plasmatiques de lercanidipine et de ciclosporine a été observée après administration concomitante des 2 principes actifs.', 'Cependant, l''administration concomitante de lercanidipine et de ciclosporine a provoqué une augmentation de 3 fois les concentrations plasmatiques de lercanidipine et une augmentation de 21% de l''ASC de la ciclosporine.', 'La ciclosporine et la lercanidipine ne doivent pas être administrées ensemble (voir rubrique 4.3).', 'Jus de pamplemousse ou de pamplemousse', 'La lercanidipine ne doit pas être prise avec du pamplemousse ou du jus de pamplemousse (voir rubrique 4.3).', 'Associations déconseillées', 'Inducteurs du cytochrome CYP3A4']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent', 'Peu fréquent']);

END
